// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 fuzz_blocks, uint256 fuzz_timestamp) public {
        uint256 nCalls = bound(fuzz_blocks, 1, 100);
        uint256 startTime = bound(fuzz_timestamp, 1, type(uint64).max);

        address caller = makeAddr("caller");
        vm.deal(caller, 10 ether * nCalls);

        vm.warp(startTime);
        vm.roll(1);

        vm.startPrank(caller);
        for (uint256 i = 0; i < nCalls; i++) {
            vm.warp(startTime + 1 + i);
            vm.roll(1 + i + 1);
            (bool ok,) = address(c).call{value: 10 ether}("");
            if (i == nCalls - 1) {
                bool lastCallOk = ok;
                vm.stopPrank();
                if (lastCallOk) {
                    assertTrue(block.timestamp == c.pastBlockTime());
                } else {
                    assertTrue(true);
                }
                return;
            }
        }
        vm.stopPrank();
    }
}
